INSERT INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, description, source_book)
VALUES
  ('field-radio-nb', 'Field Radio', 'nightbane', 'gear', 16, 1400, 'good availability', NULL, 0, '60 miles (96km)', NULL, NULL, NULL, NULL, 'A back-pack style radio transmitter and receiver with wide band, long-range capabilities, frequency equalizer, field strength detector and scrambler. Printed weight 16lbs (7kg).', 'Nightbane RPG p.225'),
  ('back-pack-radio-nb', 'Back-Pack Radio', 'nightbane', 'gear', NULL, 925, NULL, NULL, 0, '35 miles (56km)', NULL, NULL, NULL, NULL, 'A Japanese updated version of the old PRC-25, the RKO-68. Built-in scrambler and up to 1500 channels; also receives commercial AM/FM, television (sound only) and short-wave signals.', 'Nightbane RPG p.225'),
  ('belt-radio-nb', 'Belt Radio', 'nightbane', 'gear', 2, 115, NULL, NULL, 0, '2 to 3 miles', NULL, NULL, NULL, NULL, 'A lightweight unit designed to work with the RKO-68. Scrambler equipped, up to 10 preset channels, weighs only 2lbs complete with pouch and telephone-style handset. RKO-12.', 'Nightbane RPG p.225'),
  ('headset-receiver-nb', 'Headset Receiver', 'nightbane', 'gear', NULL, 42, NULL, NULL, 0, '2 miles', NULL, NULL, NULL, NULL, 'A receiver-only unit easily attached to a helmet. Built-in scrambler.', 'Nightbane RPG p.225'),
  ('hand-held-communicator-nb', 'Hand-Held Communicator', 'nightbane', 'gear', 0.375, 3200, '$3200 per single unit', NULL, 0, '3 miles (4.8km)', NULL, NULL, NULL, NULL, 'Basically an enhanced walkie-talkie, a basic instrument issued to all military personnel and field operatives. A high-tech item available only to the special branches of the military (espionage) and major scientific organizations/industries. Printed weight 6 ounces (170grams).', 'Nightbane RPG p.225'),
  ('ear-mike-radio-receiver-and-transmitter-nb', 'Ear Mike Radio Receiver and Transmitter', 'nightbane', 'gear', 0.375, 500, NULL, NULL, 0, '1 mile', NULL, NULL, NULL, NULL, 'A tough, reliable radio device that plugs into the ear. With a transducer connected to a receiver/transmitter device, manually activated for speak or listening modes, the user both listens and speaks through the earphones, because the ear canal captures outgoing sound (your voice) as well as incoming sound; it can transmit a whisper. Compatible with any portable two-way radio equipped with an external speaker/microphone. Power source is one AA 1.5 volt battery. Printed weight 6 ounces (170 grams).', 'Nightbane RPG p.225'),
  ('keyhole-or-tube-microphones-nb', 'Keyhole or Tube Microphones', 'nightbane', 'gear', NULL, 170, 'fair availability', NULL, 0, 'transmits up to 1000ft (300m)', NULL, NULL, NULL, NULL, 'A microphone with a long, hollow tube, flexible or stiff, that can be placed in cracks, mounted in walls or placed in similar small keyhole-type crevices. Picks up sounds up to 34ft (10m) away.', 'Nightbane RPG p.225'),
  ('contact-microphone-nb', 'Contact Microphone', 'nightbane', 'gear', NULL, 170, 'fair availability', NULL, 0, 'transmits up to 1000ft (300m)', NULL, NULL, NULL, NULL, 'Translates vibrations into sound, but requires a sounding board such as a wall, window or large object. Can be as small as a tie tack. Picks up sounds up to 10 meters away.', 'Nightbane RPG p.225'),
  ('commercial-wireless-microphone-nb', 'Commercial Wireless Microphone', 'nightbane', 'gear', NULL, 50, '$50-100', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'The entertainment type. Printed 225.', 'Nightbane RPG p.225'),
  ('compact-commercial-wireless-microphone-nb', 'Compact Commercial Wireless Microphone', 'nightbane', 'gear', NULL, 70, '$70-$150', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'About the size of a pack of cigarettes. A separate entry from the Commercial Wireless Microphone above it, with its own price.', 'Nightbane RPG p.225'),
  ('wireless-microphone-nb', 'Wireless Microphone', 'nightbane', 'gear', NULL, 500, 'poor availability', NULL, 0, 'picks up to 14ft, broadcasts up to 300ft', NULL, NULL, NULL, NULL, 'A compact mic about the size and thickness of a box of matches.', 'Nightbane RPG p.225'),
  ('tracer-bug-nb', 'Tracer Bug', 'nightbane', 'gear', NULL, 140, 'fair availability', NULL, 0, 'followed up to 8 miles (12km)', NULL, NULL, NULL, NULL, 'A tiny device about the size of a checker, with a sticky or magnetic side, attached to a vehicle or slipped into a pocket, back pack or briefcase. Battery powered, with a limited life of 72 hours of constant transmission.', 'Nightbane RPG p.225'),
  ('bumper-beeper-nb', 'Bumper Beeper', 'nightbane', 'gear', NULL, 1100, '$1100.00, and the price INCLUDES the receiver', NULL, 0, 'up to five miles', NULL, NULL, NULL, NULL, 'Attaches to an automobile bumper by magnetized clip, with a permanently mounted or detachable antenna. Battery powered. The receiver picks up and locates the beeper by the intensity/strength of the signal.', 'Nightbane RPG p.225'),
  ('tie-clasp-microphone-nb', 'Tie Clasp Microphone', 'nightbane', 'gear', NULL, 15, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 225 heads this simply Tie Clasp, under the Listening (bugging) Device group whose average range is 600ft.', 'Nightbane RPG p.225'),
  ('electret-condenser-lavalier-mic-nb', 'Electret Condenser Lavalier Mic.', 'nightbane', 'gear', NULL, 50, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Can be hung around the neck or attached to cloth. Battery operated or plugged in.', 'Nightbane RPG p.225'),
  ('broadcast-quality-tie-tack-nb', 'Broadcast Quality Tie Tack', 'nightbane', 'gear', NULL, 160, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 225, under the Listening (bugging) Device group.', 'Nightbane RPG p.225'),
  ('special-bugs-nb', 'Special Bugs', 'nightbane', 'gear', NULL, 400, NULL, NULL, 0, 'average 60ft', NULL, NULL, NULL, NULL, 'A variety of sizes from postage stamp to martini-olive type, complete with mic, transmitter and amplifier.', 'Nightbane RPG p.225'),
  ('room-bug-homemade-nb', 'Room Bug (homemade)', 'nightbane', 'gear', NULL, 100, '$100 homemade; printed 225 prices a police version of the same bug at $500', NULL, 0, '1200ft', NULL, NULL, NULL, NULL, 'Taps into the wall current and needs a capacitor.', 'Nightbane RPG p.225'),
  ('room-bug-police-version-nb', 'Room Bug (police version)', 'nightbane', 'gear', NULL, 500, 'the police version of the $100 homemade bug on the same page', NULL, 0, '1200ft', NULL, NULL, NULL, NULL, 'Taps into the wall current and needs a capacitor.', 'Nightbane RPG p.225'),
  ('transmitters-typical-nb', 'Transmitters (typical)', 'nightbane', 'gear', NULL, 200, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A bugging transmitter, typical grade. Printed 225, Listening (bugging) Device group.', 'Nightbane RPG p.225'),
  ('transmitters-quality-crystal-nb', 'Transmitters (quality crystal)', 'nightbane', 'gear', NULL, 500, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A bugging transmitter, quality crystal grade. Printed 225, Listening (bugging) Device group.', 'Nightbane RPG p.225'),
  ('low-frequency-converter-nb', 'Low-Frequency Converter', 'nightbane', 'gear', NULL, 500, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 225, Listening (bugging) Device group. Priced on its own line, separate from the Frequency Equalizer below it.', 'Nightbane RPG p.225'),
  ('frequency-equalizer-nb', 'Frequency Equalizer', 'nightbane', 'gear', NULL, 190, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Controls the cutoff of certain frequencies and boosts others.', 'Nightbane RPG p.225'),
  ('test-transmitter-nb', 'Test Transmitter', 'nightbane', 'gear', NULL, 65, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 225.', 'Nightbane RPG p.225'),
  ('additional-transducer-nb', 'Additional Transducer', 'nightbane', 'gear', NULL, 75, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 225.', 'Nightbane RPG p.225'),
  ('telephone-induction-unit-nb', 'Telephone Induction Unit', 'nightbane', 'gear', NULL, 65, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 225.', 'Nightbane RPG p.225'),
  ('sound-amplifier-nb', 'Sound Amplifier', 'nightbane', 'gear', NULL, 50, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 225.', 'Nightbane RPG p.225'),
  ('sound-amplifier-high-quality-nb', 'Sound Amplifier (high quality)', 'nightbane', 'gear', NULL, 250, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A separate entry from the $50 Sound Amplifier directly above it on printed 225.', 'Nightbane RPG p.225'),
  ('drop-in-cartridge-nb', 'Drop in Cartridge', 'nightbane', 'gear', NULL, 320, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A telephone bug: battery powered, fits in the telephone receiver.', 'Nightbane RPG p.225'),
  ('room-bug-mini-transmitter-nb', 'Room Bug Mini-Transmitter', 'nightbane', 'gear', NULL, 240, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A telephone bug that looks like a telephone jack. Battery operated.', 'Nightbane RPG p.226'),
  ('telephone-line-transmitter-nb', 'Telephone Line Transmitter', 'nightbane', 'gear', NULL, 250, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A telephone bug that taps right into the telephone line and its power, so it needs no batteries and runs indefinitely. A little larger box than the mini-transmitter.', 'Nightbane RPG p.226'),
  ('field-strength-meter-nb', 'Field Strength Meter', 'nightbane', 'gear', NULL, 350, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A bug detector: picks up radio signals and registers them.', 'Nightbane RPG p.226'),
  ('broadband-receiver-nb', 'Broadband Receiver', 'nightbane', 'gear', NULL, 425, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A bug detector: causes feedback and makes a howl when near a transmitter.', 'Nightbane RPG p.226'),
  ('pocket-vibration-detector-nb', 'Pocket Vibration Detector', 'nightbane', 'gear', NULL, 600, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 226, under Bug Detectors.', 'Nightbane RPG p.226'),
  ('pocket-scrambler-nb', 'Pocket Scrambler', 'nightbane', 'gear', NULL, 1300, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Distorts or scrambles outgoing radio signals, preventing interception and interpretation by the enemy.', 'Nightbane RPG p.226'),
  ('portable-telephone-scrambler-nb', 'Portable Telephone Scrambler', 'nightbane', 'gear', NULL, 1400, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Converts normal speech into unintelligible gibberish over the telephone line and converts the gibberish back into clear speech. 25 different scrambling codes. Fully transistorized and usable on any conventional phone. Comes with an impact resistant carrying case.', 'Nightbane RPG p.226'),
  ('video-briefcase-nb', 'Video Briefcase', 'nightbane', 'gear', NULL, 3400, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'An ordinary looking briefcase with a video recording surveillance system built in. The tiny pinhole lens is nearly invisible (18% chance of it being noticed). Three hour film capacity. Reinforced, impact cushioned case with a back-up mini-cassette tape recorder.', 'Nightbane RPG p.226'),
  ('video-wall-mount-nb', 'Video Wall Mount', 'nightbane', 'gear', NULL, 3200, 'Not available through the conventional market', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A small remote video camera about the size of a man''s palm (5 inches in diameter), easily concealed, backed with a powerful suction device that adheres to any smooth surface. Broadcasts continually for 72 hours, or by remote or preprogrammed regulated intervals. The lens rotates in about a 90 degree radius. Audio lasts twice the duration of the video transmission and picks up sounds up to twenty feet (6m) away with crystal clarity. The monitor can be the mini hand-held screen or larger or multi-unit monitors. Not available through the conventional market, but a hot commodity on the black market. Printed 226 prices its hand-held monitor separately at $450.', 'Nightbane RPG p.226'),
  ('video-wall-mount-hand-held-monitor-nb', 'Video Wall Mount Hand-Held Monitor', 'nightbane', 'gear', NULL, 450, '$450; a hot commodity on the black market', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'The monitor for the Video Wall Mount, priced separately on printed 226.', 'Nightbane RPG p.226'),
  ('mini-telephoto-document-camera-nb', 'Mini-Telephoto Document Camera', 'nightbane', 'gear', NULL, 350, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A tiny, easy to conceal camera, only a little bigger than a disposable lighter.', 'Nightbane RPG p.226');
INSERT INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, description, source_book)
VALUES
  ('dosimeter-nb', 'Dosimeter', 'nightbane', 'gear', 1, 200, 'wide availability', NULL, 0, '20ft (6.1m)', NULL, NULL, NULL, NULL, 'Hand-held. Picks up and measures radiation levels. Printed weight 1lb (.5kg).', 'Nightbane RPG p.226'),
  ('ground-sensor-system-nb', 'Ground Sensor System', 'nightbane', 'gear', NULL, 48500, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Uses seismic and laser sensors to detect vehicles/men, their direction and their numbers; a good communications engineer can make such projections with 75% accuracy. The control unit, with digital display, computer mount and monitor, is the center of the sensor web; up to 22 transmitter/receiver sensor units can be linked to it. Range between transmitters is 800ft (240m) and it can register activity up to 10 miles (16km) away. Generally limited to the military and scientific research.', 'Nightbane RPG p.226'),
  ('heat-sensor-nb', 'Heat Sensor', 'nightbane', 'gear', 8, 1200, NULL, NULL, 0, '250ft (76m)', NULL, NULL, NULL, NULL, 'Special sensors pick up and measure heat emanations; can monitor temperature, or be made directional to pinpoint a specific heat point/target. Field of detection is 25ft (7.6m). Portable/hand held. Printed weight 8lbs (3.6kg). Printed 226 heads this row simply Heat, among the sensory equipment; named in full here so it is legible out of that group.', 'Nightbane RPG p.226'),
  ('microwave-fence-nb', 'Microwave Fence', 'nightbane', 'gear', NULL, 60000, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Transmitter and receiver sensor posts emit an invisible microwave curtain that lights up and sends a signal to the control unit when an intruder breaches it. Range between transmitter posts is 500ft (150m); posts are 7ft (2m) high; can effectively cover a 14 mile (22km) area. Primarily used for military purposes.', 'Nightbane RPG p.226'),
  ('motion-sensor-nb', 'Motion Sensor', 'nightbane', 'gear', 15, 400, 'fair availability', NULL, 0, '60ft (27.4m)', NULL, NULL, NULL, NULL, 'Detects movement and pinpoints location. Requires sensor placement and monitor screen. Portable. Printed total weight 15lbs (6.8kg). Printed 226 heads this row simply Motion, among the sensory equipment.', 'Nightbane RPG p.226'),
  ('motion-detector-signaler-nb', 'Motion Detector Signaler', 'nightbane', 'gear', NULL, 1000, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Virtually identical in purpose and use to the ultraviolet signaler, except that it does not emit any vibrations in the air.', 'Nightbane RPG p.226'),
  ('mini-radar-sonar-nb', 'Mini-Radar/Sonar', 'nightbane', 'gear', 18, 22500, 'fair availability', NULL, 0, '5 miles (8km)', NULL, NULL, NULL, NULL, 'Requires a radar signal unit and monitor. Trained operators (sensory equipment skill) can positively identify readings/objects, pinpoint location and estimate rate of travel and direction at 65% proficiency. Portable. Printed total weight 18lbs (8.2kg).', 'Nightbane RPG p.226'),
  ('standard-radar-sonar-unit-large-nb', 'Standard Radar/Sonar Unit (large)', 'nightbane', 'gear', 260, 26000, NULL, NULL, 0, '100 miles (160km)', NULL, NULL, NULL, NULL, 'Printed weight 260lbs (117kg).', 'Nightbane RPG p.226'),
  ('ultraviolet-signaler-nb', 'Ultraviolet Signaler', 'nightbane', 'gear', NULL, 900, 'fair availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A small strip of ultraviolet sensors and a transmitter strip adhered to a doorway, walls and so on, creating a beam of invisible light across that area. When the beam is broken by an intruder or vehicle it sends a silent signal to a monitoring device and/or triggers a video unit.', 'Nightbane RPG p.226'),
  ('portable-laboratory-nb', 'Portable Laboratory', 'nightbane', 'gear', 58, 42000, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A portable unit with several functions: (1) microscope in a specially padded housing; (2) one dozen specimen slides and a dozen specimen trays, plus vials, jars and test tubes; (3) an incubation chamber about the size of a VCR (1 1/2ft x 1ft x 8in deep); (4) four burners; (5) instrument tray with scalpels, tweezers, pins, tape, needles, calculator, etc.; (6) a refrigeration chamber about half the size of the incubation chamber; (7) an airtight, sealable isolation chamber about the size of the incubation chamber; (8) a chemical cabinet of several dozen chemicals; (9) centrifuge device; (10) dosimeter; (11) tape recorder; (12) mini-computer; (13) mini-still camera, 35mm, 32 photo capacity; (14) toxic analyzer identical to the one in the portable bio-scan. Printed weight of the whole unit 58lbs (26kg). The entry begins on printed 226 and its price is on 227.', 'Nightbane RPG p.226-227'),
  ('portable-scan-dihilator-nb', 'Portable Scan Dihilator', 'nightbane', 'gear', NULL, 50000, 'about $50,000; poor availability, usually limited to scientific research and the military', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A uniquely comprehensive sensory device with full scanning capabilities: (1) radar/sonar limited to a 5 mile area, a trained operator (sensory equipment skill) identifying readings as specific objects or vehicles, pinpointing location and estimating rate of travel and direction at 65% proficiency; (2) dosimeter, radar detector, heat, infrared, ultraviolet, microwave and energy sensitive instruments, all of which identify, locate source and record; (3) long-range wide band radio with scrambler, 40 mile radius; (4) detachable short-range hand-held communicator, 3 miles; (5) mini video camera with wide and narrow angle lenses, audio-visual recorder using metal discs with digital meter, lens filters, telescopic lens (480m) and tripod, capable of radio telemetry when boosted by the long-range radio.', 'Nightbane RPG p.227'),
  ('amplified-sound-detector-nb', 'Amplified Sound Detector', 'nightbane', 'gear', 2, 160, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Designed for professional hunters to hear approaching game; also used by the security industry. A two-piece unit of headphones and a sound detector that at first glance resembles a very large flashlight, with a built-in 3 1/2 inch parabolic dish for sound mirror effect. Triples the normal human range of hearing. Printed weight about 2lbs (.9kg).', 'Nightbane RPG p.227'),
  ('bug-detector-nb', 'Bug Detector', 'nightbane', 'gear', NULL, 350, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A small hand-held device that picks up radio signals from listening devices (bugs).', 'Nightbane RPG p.227'),
  ('letter-bomb-detector-nb', 'Letter Bomb Detector', 'nightbane', 'gear', NULL, 700, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'An electronic instrument that examines letters in minutes, with an audio alarm that sounds when electrically conductive material is detected.', 'Nightbane RPG p.227'),
  ('portable-explosives-detector-nb', 'Portable Explosives Detector', 'nightbane', 'gear', NULL, 1900, NULL, NULL, 0, '3.5ft', NULL, NULL, NULL, NULL, 'Responds to vapor from explosives such as dynamite, gelignite and T.N.T.; an alarm lamp lights up when an explosive is detected. Printed range 3 1/2ft.', 'Nightbane RPG p.227'),
  ('radar-signal-detector-military-nb', 'Radar Signal Detector (military)', 'nightbane', 'gear', NULL, 3000, NULL, NULL, 0, '80ft effective, 4 miles maximum', NULL, NULL, NULL, NULL, 'A mini-radar receiver that fits in one hand. Small, lightweight, easy to conceal. Recently developed for the U.S. Army.', 'Nightbane RPG p.227'),
  ('commercial-radar-detector-nb', 'Commercial Radar Detector', 'nightbane', 'gear', NULL, 120, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Also known as the Fuzz Buster because of its use in detecting police radar scans.', 'Nightbane RPG p.227'),
  ('psychological-stress-evaluator-nb', 'Psychological Stress Evaluator', 'nightbane', 'gear', NULL, 4000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Used by law enforcement agencies, private investigators, some private corporations, clinics and law firms. Functions like a polygraph machine but measures and records stress and anxiety without attaching sensors to the subject, by monitoring the voice quality of its subject. A tape recorder is part of the device.', 'Nightbane RPG p.227'),
  ('polygraph-stress-machine-nb', 'Polygraph Stress Machine', 'nightbane', 'gear', NULL, 2400, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Sensors attached to the skin monitor and record glandular changes (including sweat) in the skin.', 'Nightbane RPG p.227'),
  ('polygraph-stress-monitor-nb', 'Polygraph Stress Monitor', 'nightbane', 'gear', NULL, 4500, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Superior quality. Sensors attached to the skin and body usually record breathing, heart beat/rate, blood pressure and skin resistance; all three functions are fed into a chart recorder with three pens to mark the results.', 'Nightbane RPG p.227'),
  ('35mm-camera-nb', '35mm Camera', 'nightbane', 'gear', NULL, 250, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227, PHOTOGRAPHIC EQUIPMENT.', 'Nightbane RPG p.227'),
  ('camera-lens-28mm-f2-8-nb', 'Camera Lens, 28mm F2.8', 'nightbane', 'gear', NULL, 80, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'An extra lens for the 35mm camera, printed 227.', 'Nightbane RPG p.227'),
  ('camera-lens-135mm-f3-5-nb', 'Camera Lens, 135mm F3.5', 'nightbane', 'gear', NULL, 80, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'An extra lens for the 35mm camera, printed 227.', 'Nightbane RPG p.227'),
  ('camera-flash-average-nb', 'Camera Flash (average)', 'nightbane', 'gear', NULL, 50, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227, listed under Extra Lenses.', 'Nightbane RPG p.227'),
  ('35mm-film-black-and-white-36-exposure-nb', '35mm Film, Black and White, 36 exposure', 'nightbane', 'gear', NULL, NULL, '$2.50 - below the resolution of an integer cost column, so it is recorded here rather than rounded', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227.', 'Nightbane RPG p.227'),
  ('35mm-film-color-36-exposure-nb', '35mm Film, Color, 36 exposure', 'nightbane', 'gear', NULL, NULL, '$4.50 - below the resolution of an integer cost column', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227.', 'Nightbane RPG p.227'),
  ('super-8mm-sound-movie-camera-nb', 'Super 8mm Sound Movie Camera', 'nightbane', 'gear', NULL, 525, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227.', 'Nightbane RPG p.227'),
  ('super-8mm-film-nb', 'Super 8mm Film', 'nightbane', 'gear', NULL, 8, '$8.00 for approximately 15 minutes running time', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227.', 'Nightbane RPG p.227'),
  ('slide-projector-nb', 'Slide Projector', 'nightbane', 'gear', NULL, 150, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227.', 'Nightbane RPG p.227'),
  ('projection-screen-nb', 'Projection Screen', 'nightbane', 'gear', NULL, 50, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227.', 'Nightbane RPG p.227'),
  ('vhs-video-recorder-nb', 'VHS Video Recorder', 'nightbane', 'gear', NULL, 500, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227.', 'Nightbane RPG p.227'),
  ('beta-video-recorder-nb', 'Beta Video Recorder', 'nightbane', 'gear', NULL, 400, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227.', 'Nightbane RPG p.227'),
  ('video-camera-with-tripod-nb', 'Video Camera with Tripod', 'nightbane', 'gear', NULL, 2000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227.', 'Nightbane RPG p.227'),
  ('full-video-studio-nb', 'Full Video Studio', 'nightbane', 'gear', NULL, 180000, '$180,000 for the BASIC system', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'With editing, dubbing, optical enhancements and full film capabilities.', 'Nightbane RPG p.227'),
  ('color-camera-with-mike-nb', 'Color Camera with Mike', 'nightbane', 'gear', NULL, 700, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227.', 'Nightbane RPG p.227'),
  ('videotape-cassette-nb', 'Videotape Cassette', 'nightbane', 'gear', NULL, 10, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227.', 'Nightbane RPG p.227'),
  ('telescope-zoom-15-60x-power-nb', 'Telescope, zoom 15-60X power', 'nightbane', 'gear', NULL, 190, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '1000-4000mm when attached to a 35mm camera.', 'Nightbane RPG p.227'),
  ('35mm-camera-adapter-nb', '35mm Camera Adapter', 'nightbane', 'gear', NULL, 30, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227.', 'Nightbane RPG p.227'),
  ('mask-snorkel-and-fin-package-nb', 'Mask, Snorkel and Fin Package', 'nightbane', 'gear', NULL, 110, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 227, UNDERWATER EQUIPMENT.', 'Nightbane RPG p.227'),
  ('s-c-u-b-a-package-nb', 'S.C.U.B.A. Package', 'nightbane', 'gear', NULL, 820, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'An 80K cylinder with boot, datacom double console (PSI depth), regulator, wet suit, pack and power. Oxygen capacity 90 minutes.', 'Nightbane RPG p.227');
INSERT INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, description, source_book)
VALUES
  ('compact-s-c-u-b-a-nb', 'Compact S.C.U.B.A.', 'nightbane', 'gear', NULL, 155, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A one unit, 2 cubic foot capacity cylinder (air tank) with the regulator mounted on top and a belt holder. Overall length 17 inches x 2 1/2 inches wide. Great for short dives or emergency air supply. Oxygen capacity 15 minutes.', 'Nightbane RPG p.227'),
  ('mini-s-c-u-b-a-nb', 'Mini S.C.U.B.A.', 'nightbane', 'gear', NULL, 300, 'Not commercially available; espionage', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A tiny air tank and regulator measuring 5 x 2 1/2 inches. Oxygen capacity a mere four minutes.', 'Nightbane RPG p.227'),
  ('diver-s-watch-nb', 'Diver''s Watch', 'nightbane', 'gear', NULL, 300, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Multifunctional digital and analog (hands) display, alarm, two time zones, timer, rotating bezel, sweep second hand.', 'Nightbane RPG p.227'),
  ('dive-flasher-nb', 'Dive Flasher', 'nightbane', 'gear', NULL, 30, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A waterproof beacon or rescue marker, waterproof up to 150ft, measuring 5 x 1 1/2 inches; operates on one C battery.', 'Nightbane RPG p.227'),
  ('mini-flashlight-nb', 'Mini Flashlight', 'nightbane', 'gear', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Overall length 4 3/4 x 3/4 inches; uses 2 AA batteries; features pocket clip, magnetic butt, and screw down... The entry is cut off mid-sentence at the foot of printed 227 and printed 228 opens with CONTAINERS, so the book prints no price for it.', 'Nightbane RPG p.227');
